/**
 * @distilled.cloud/tencentcloud -- Tencent Cloud API 3.0 SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the API models Tencent ships in its
 * CLI, mirrored at `specs/spec-mirror-tencentcloud/specs/`. Everything else
 * in this folder is hand-written.
 *
 * One module per product, named as the CLI names it (`cvm`, `vpc`, `cbs`,
 * `autoscaling`, `dnspod`, ...). Each is also importable on its own as
 * `@distilled.cloud/tencentcloud/<product>`.
 *
 * @example
 * ```ts
 * import * as TencentCloud from "@distilled.cloud/tencentcloud";
 *
 * const { InstanceSet } = yield* TencentCloud.cvm.describeInstances({
 *   region: "ap-guangzhou",
 *   Limit: 10,
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export * as Region from "./region.ts";
export * as Retry from "./retry.ts";
export * as Signer from "./signer.ts";
export {
  TencentCloudProtocol,
  type TencentCloudOpError,
  type TencentCloudOpContext,
} from "./protocol.ts";
export * from "./services/index.ts";
